]
for path in sys.argv[1:]:
    users=[]; n_user=n_asst=0; tools={}
    secret_hits={}
    raw = open(path, encoding='utf-8', errors='replace').read()
    for name,pat in SECRET_PATTERNS:
        c=len(pat.findall(raw))
        if c: secret_hits[name]=c
    for line in raw.splitlines():
        line=line.strip()
        if not line: continue
        try: o=json.loads(line)
        except: continue
        t=o.get('type')
        msg=o.get('message',{}) or {}
        if t=='user':
            n_user+=1
            c=msg.get('content')
            txt=None
            if isinstance(c,str): txt=c
            elif isinstance(c,list):
                for b in c:
                    if isinstance(b,dict) and b.get('type')=='text': txt=b.get('text'); break
            if txt and not txt.startswith('<') and 'tool_result' not in str(c)[:40]:
                if len(users)<2: users.append(' '.join(txt.split())[:180])
        elif t=='assistant':
            n_asst+=1
            c=msg.get('content')
            if isinstance(c,list):
                for b in c:
